import React, { useEffect, useState } from "react";
import axios from "axios";
import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement);

function App() {
  const [data, setData] = useState([]);
  const [page, setPage] = useState("dashboard");

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 3000);
    return () => clearInterval(interval);
  }, []);

  const loadData = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/data");
      console.log("DATA:", res.data); // debug
      setData(res.data);
    } catch (err) {
      console.log("ERROR API:", err);
    }
  };

  const latest = data.length > 0 ? data[0] : null;

  const getColor = (kondisi) => {
    if (kondisi === "PEMBOROSAN") return "#ef4444";
    if (kondisi === "PERINGATAN") return "#f59e0b";
    if (kondisi === "NORMAL") return "#22c55e";
    return "#94a3b8";
  };

  const chartData = {
    labels: data.map(d => d.waktu).reverse(),
    datasets: [
      {
        label: "Jumlah Orang",
        data: data.map(d => d.jumlah_orang).reverse(),
        borderColor: "#22c55e"
      }
    ]
  };

  return (
    <div style={{ display: "flex", background: "#0f172a", color: "white", minHeight: "100vh" }}>

      {/* SIDEBAR */}
      <div style={{ width: 220, padding: 20, background: "#1e293b" }}>
        <h2>Hematrik</h2>
        <p onClick={() => setPage("dashboard")} style={{cursor:"pointer"}}>Dashboard</p>
        <p onClick={() => setPage("monitoring")} style={{cursor:"pointer"}}>Monitoring</p>
        <p onClick={() => setPage("history")} style={{cursor:"pointer"}}>History</p>
      </div>

      {/* CONTENT */}
      <div style={{ flex: 1, padding: 20 }}>

        {/* DASHBOARD */}
        {page === "dashboard" && (
          <>
            <h1>Dashboard Monitoring</h1>

            {!latest ? (
              <h2>Loading data...</h2>
            ) : (
              <>
                {/* NOTIF */}
                <div style={{
                  padding: 15,
                  borderRadius: 10,
                  marginBottom: 20,
                  background:
                    latest.kondisi === "PEMBOROSAN" || latest.kondisi === "PERINGATAN"
                      ? "#7f1d1d"
                      : "#065f46"
                }}>
                  {latest.notifikasi}
                </div>

                {/* CARD */}
                <div style={{ display: "flex", gap: 20 }}>
                  <div style={{ background:"#1e293b", padding:20, borderRadius:10 }}>
                    <h3>People</h3>
                    <h1>{latest.jumlah_orang}</h1>
                  </div>

                  <div style={{ background:"#1e293b", padding:20, borderRadius:10 }}>
                    <h3>Listrik</h3>
                    <h1>{latest.status_listrik}</h1>
                  </div>

                  <div style={{ background:"#1e293b", padding:20, borderRadius:10 }}>
                    <h3>Kondisi</h3>
                    <h1 style={{ color: getColor(latest.kondisi) }}>
                      {latest.kondisi}
                    </h1>
                  </div>
                </div>

                {/* GAMBAR */}
                <div style={{ marginTop: 20 }}>
                  <img
                    src={`http://127.0.0.1:8000/${latest.gambar}`}
                    width="300"
                    alt=""
                  />
                </div>

                {/* GRAFIK */}
                <div style={{ marginTop: 30 }}>
                  <Line data={chartData} />
                </div>
              </>
            )}
          </>
        )}

        {/* MONITORING */}
        {page === "monitoring" && latest && (
          <>
            <h1>Monitoring</h1>
            <img src={`http://127.0.0.1:8000/${latest.gambar}`} width="400" alt="" />
            <h2>{latest.jumlah_orang} orang</h2>
            <h3 style={{ color: getColor(latest.kondisi) }}>{latest.kondisi}</h3>
          </>
        )}

        {/* HISTORY */}
        {page === "history" && (
          <>
            <h1>History</h1>
            <table style={{ width: "100%" }}>
              <thead>
                <tr>
                  <th>Waktu</th>
                  <th>Orang</th>
                  <th>Listrik</th>
                  <th>Kondisi</th>
                </tr>
              </thead>
              <tbody>
                {data.map(d => (
                  <tr key={d.id}>
                    <td>{d.waktu}</td>
                    <td>{d.jumlah_orang}</td>
                    <td>{d.status_listrik}</td>
                    <td style={{ color: getColor(d.kondisi) }}>{d.kondisi}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        )}

      </div>
    </div>
  );
}

export default App;
